from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/items/")
async def read_items(
    strange_header: str | None = Header(default=None, convert_underscores=True),
):
    return {"strange_header": strange_header}

client = TestClient(app)

def test_underscore_header_rejected_by_default():
    # By default convert_underscores=True, so it should only accept 'strange-header'
    # and reject 'strange_header'
    response = client.get("/items/", headers={"strange_header": "FastAPI test"})
    assert response.status_code == 200
    assert response.json() == {"strange_header": None}

def test_hyphen_header_accepted_by_default():
    response = client.get("/items/", headers={"strange-header": "FastAPI test"})
    assert response.status_code == 200
    assert response.json() == {"strange_header": "FastAPI test"}

app_no_convert = FastAPI()

@app_no_convert.get("/items_no_convert/")
async def read_items_no_convert(
    strange_header: str | None = Header(default=None, convert_underscores=False),
):
    return {"strange_header": strange_header}

client_no_convert = TestClient(app_no_convert)

def test_underscore_header_accepted_when_convert_underscores_false():
    response = client_no_convert.get("/items_no_convert/", headers={"strange_header": "FastAPI test"})
    assert response.status_code == 200
    assert response.json() == {"strange_header": "FastAPI test"}

def test_hyphen_header_rejected_when_convert_underscores_false():
    response = client_no_convert.get("/items_no_convert/", headers={"strange-header": "FastAPI test"})
    assert response.status_code == 200
    assert response.json() == {"strange_header": None}

